export const DASHBOARD_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>SmartFlow Intelligence — Operations Dashboard</title>\n  <style>\n    :root {\n      --bg: #0b1020;\n      --surface: #121a2f;\n      --surface-2: #18233f;\n      --border: #253357;\n      --text: #e6ecf8;\n      --muted: #93a4c7;\n      --accent: #4f8cff;\n      --accent-hover: #3b78f0;\n      --green: #22c55e;\n      --amber: #f59e0b;\n      --red: #ef4444;\n      --purple: #a855f7;\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0;\n      font-family: Inter, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n      background: var(--bg);\n      color: var(--text);\n      line-height: 1.5;\n    }\n    header {\n      position: sticky;\n      top: 0;\n      z-index: 20;\n      background: rgba(11, 16, 32, 0.9);\n      backdrop-filter: blur(10px);\n      border-bottom: 1px solid var(--border);\n      padding: 14px 24px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n    }\n    .brand {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      font-weight: 700;\n      font-size: 1.05rem;\n    }\n    .dot {\n      width: 10px;\n      height: 10px;\n      border-radius: 50%;\n      background: var(--green);\n      box-shadow: 0 0 10px var(--green);\n    }\n    .controls {\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      gap: 8px;\n    }\n    input, select, button {\n      background: var(--surface-2);\n      color: var(--text);\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      padding: 8px 12px;\n      font-size: 0.875rem;\n    }\n    button {\n      cursor: pointer;\n      font-weight: 500;\n      transition: background 0.15s, border-color 0.15s;\n    }\n    button:hover { border-color: var(--accent); }\n    button.primary {\n      background: var(--accent);\n      border-color: var(--accent);\n      color: #fff;\n    }\n    button.primary:hover { background: var(--accent-hover); }\n    button:disabled { opacity: 0.5; cursor: not-allowed; }\n\n    main {\n      max-width: 1380px;\n      margin: 0 auto;\n      padding: 20px 24px 60px;\n    }\n    .banner {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: 10px;\n      padding: 12px 16px;\n      margin-bottom: 18px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      font-size: 0.875rem;\n      color: var(--muted);\n    }\n    .banner.error { border-color: var(--red); color: #fecaca; background: rgba(239, 68, 68, 0.12); }\n\n    .grid-kpi {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));\n      gap: 14px;\n      margin-bottom: 20px;\n    }\n    .card {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 16px 18px;\n    }\n    .kpi-card {\n      cursor: pointer;\n      transition: transform 0.14s ease, border-color 0.14s ease, box-shadow 0.14s ease;\n    }\n    .kpi-card:hover {\n      transform: translateY(-2px);\n      border-color: var(--accent);\n    }\n    .kpi-card.active-filter, .agent-card.active-filter, .outcome-row.active-filter {\n      border-color: var(--accent) !important;\n      box-shadow: 0 0 0 2px rgba(79, 140, 255, 0.35);\n    }\n    .agent-card { cursor: pointer; transition: transform 0.12s ease, border-color 0.12s ease; }\n    .agent-card:hover { transform: translateY(-1px); border-color: var(--accent); }\n    .outcome-row {\n      cursor: pointer;\n      padding: 4px 6px;\n      border-radius: 6px;\n      border: 1px solid transparent;\n      transition: background 0.12s ease, border-color 0.12s ease;\n    }\n    .outcome-row:hover { background: rgba(79, 140, 255, 0.08); }\n    .active-filter-bar {\n      display: none;\n      align-items: center;\n      gap: 8px;\n      margin-bottom: 12px;\n      font-size: 0.82rem;\n    }\n    .active-filter-bar.show { display: flex; flex-wrap: wrap; }\n    .filter-pill {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      background: rgba(79, 140, 255, 0.18);\n      border: 1px solid rgba(79, 140, 255, 0.5);\n      color: #bfdbfe;\n      padding: 4px 10px;\n      border-radius: 99px;\n      font-weight: 600;\n    }\n    .filter-pill button {\n      background: transparent;\n      border: none;\n      color: #fff;\n      padding: 0 2px;\n      font-size: 0.85rem;\n      cursor: pointer;\n    }\n    .kpi-label { font-size: 0.78rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.04em; }\n    .kpi-value { font-size: 1.75rem; font-weight: 700; margin-top: 4px; }\n    .kpi-sub { font-size: 0.8rem; color: var(--muted); margin-top: 4px; }\n\n    .progress {\n      width: 100%;\n      height: 7px;\n      background: var(--surface-2);\n      border-radius: 99px;\n      overflow: hidden;\n      margin-top: 8px;\n    }\n    .progress > div {\n      height: 100%;\n      background: linear-gradient(90deg, var(--accent), var(--green));\n      transition: width 0.3s ease;\n    }\n\n    .grid-2 {\n      display: grid;\n      grid-template-columns: 1.35fr 1fr;\n      gap: 16px;\n      margin-bottom: 20px;\n    }\n    @media (max-width: 960px) { .grid-2 { grid-template-columns: 1fr; } }\n\n    /* Compact Color-Coded Telecaller Cards */\n    .agent-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));\n      gap: 10px;\n      max-height: 320px;\n      overflow-y: auto;\n      padding-right: 4px;\n    }\n    .agent-card {\n      background: var(--surface-2);\n      border: 1px solid var(--border);\n      border-left: 4px solid var(--muted);\n      border-radius: 10px;\n      padding: 10px 12px;\n      font-size: 0.8rem;\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n    .agent-card.tier-high { border-left-color: var(--green); background: linear-gradient(135deg, rgba(34,197,94,0.08), var(--surface-2)); }\n    .agent-card.tier-mid  { border-left-color: var(--amber); background: linear-gradient(135deg, rgba(245,158,11,0.08), var(--surface-2)); }\n    .agent-card.tier-low  { border-left-color: var(--red);   background: linear-gradient(135deg, rgba(239,68,68,0.08), var(--surface-2)); }\n    .agent-card.tier-idle { border-left-color: #475569; opacity: 0.72; }\n    .agent-top { display: flex; justify-content: space-between; align-items: center; gap: 6px; }\n    .agent-name { font-weight: 700; font-size: 0.86rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n    .agent-stats { display: flex; justify-content: space-between; color: var(--muted); font-size: 0.75rem; }\n    .mini-bar { width: 100%; height: 5px; background: rgba(148,163,184,0.18); border-radius: 99px; overflow: hidden; }\n    .mini-bar > div { height: 100%; border-radius: 99px; }\n\n    /* Outcome Breakdown Chart */\n    .outcome-chart-wrap {\n      display: flex;\n      align-items: center;\n      gap: 18px;\n      flex-wrap: wrap;\n    }\n    .donut-box { position: relative; width: 148px; height: 148px; flex-shrink: 0; }\n    .donut-center {\n      position: absolute;\n      inset: 0;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      pointer-events: none;\n    }\n    .donut-total { font-size: 1.4rem; font-weight: 700; line-height: 1.1; }\n    .donut-sub { font-size: 0.7rem; color: var(--muted); }\n    .outcome-legend { flex: 1; min-width: 190px; display: flex; flex-direction: column; gap: 8px; }\n    .outcome-row { display: flex; flex-direction: column; gap: 3px; font-size: 0.8rem; }\n    .outcome-row-top { display: flex; justify-content: space-between; align-items: center; }\n    .outcome-dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; margin-right: 6px; }\n\n    h2 {\n      margin: 0 0 12px;\n      font-size: 1rem;\n      font-weight: 600;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 8px;\n    }\n    .muted { color: var(--muted); font-size: 0.82rem; font-weight: 400; }\n\n    .queue-grid {\n      display: grid;\n      grid-template-columns: repeat(4, 1fr);\n      gap: 10px;\n    }\n    @media (max-width: 640px) { .queue-grid { grid-template-columns: repeat(2, 1fr); } }\n    .q-box {\n      background: var(--surface-2);\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      padding: 10px 12px;\n      font-size: 0.8rem;\n    }\n    .q-title { font-weight: 600; text-transform: capitalize; margin-bottom: 4px; }\n    .q-nums { color: var(--muted); display: flex; flex-wrap: wrap; gap: 8px; }\n\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      font-size: 0.85rem;\n    }\n    th, td {\n      text-align: left;\n      padding: 10px 10px;\n      border-bottom: 1px solid var(--border);\n    }\n    th {\n      color: var(--muted);\n      font-weight: 600;\n      font-size: 0.76rem;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n    }\n    tbody tr:hover { background: rgba(79, 140, 255, 0.07); }\n    tr.clickable { cursor: pointer; }\n\n    .badge {\n      display: inline-block;\n      padding: 2px 8px;\n      border-radius: 99px;\n      font-size: 0.74rem;\n      font-weight: 600;\n      text-transform: capitalize;\n    }\n    .badge.green { background: rgba(34, 197, 94, 0.18); color: #86efac; }\n    .badge.amber { background: rgba(245, 158, 11, 0.18); color: #fcd34d; }\n    .badge.red { background: rgba(239, 68, 68, 0.18); color: #fca5a5; }\n    .badge.blue { background: rgba(79, 140, 255, 0.18); color: #93c5fd; }\n    .badge.gray { background: rgba(147, 164, 199, 0.18); color: #cbd5e1; }\n\n    .modal-backdrop {\n      position: fixed;\n      inset: 0;\n      background: rgba(4, 8, 18, 0.75);\n      display: none;\n      align-items: center;\n      justify-content: center;\n      padding: 20px;\n      z-index: 50;\n    }\n    .modal-backdrop.open { display: flex; }\n    .modal {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      max-width: 760px;\n      width: 100%;\n      max-height: 86vh;\n      overflow-y: auto;\n      padding: 20px 24px;\n    }\n    pre.transcript-box {\n      background: var(--bg);\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      padding: 12px;\n      white-space: pre-wrap;\n      font-size: 0.84rem;\n      max-height: 240px;\n      overflow-y: auto;\n    }\n    .auth-box {\n      max-width: 440px;\n      margin: 80px auto;\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: 14px;\n      padding: 24px;\n    }\n    .auth-box input { width: 100%; margin: 12px 0; }\n    .auth-box button { width: 100%; }\n\n    /* Floating AI Bot Widget */\n    .bot-fab {\n      position: fixed;\n      right: 24px;\n      bottom: 24px;\n      z-index: 60;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      padding: 12px 18px;\n      border-radius: 999px;\n      background: linear-gradient(135deg, var(--accent), var(--purple));\n      border: none;\n      color: #fff;\n      font-weight: 600;\n      font-size: 0.9rem;\n      box-shadow: 0 10px 30px rgba(79, 140, 255, 0.38);\n      cursor: pointer;\n      transition: transform 0.15s ease, box-shadow 0.15s ease;\n    }\n    .bot-fab:hover {\n      transform: translateY(-2px);\n      box-shadow: 0 14px 34px rgba(79, 140, 255, 0.5);\n    }\n    .bot-panel {\n      position: fixed;\n      right: 24px;\n      bottom: 24px;\n      z-index: 65;\n      width: 400px;\n      max-width: calc(100vw - 32px);\n      height: 520px;\n      max-height: calc(100vh - 48px);\n      background: var(--surface);\n      border: 1px solid rgba(79, 140, 255, 0.45);\n      border-radius: 16px;\n      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);\n      display: none;\n      flex-direction: column;\n      overflow: hidden;\n      transition: width 0.25s ease, height 0.25s ease;\n    }\n    .bot-panel.open { display: flex; }\n    .bot-panel.expanded {\n      width: 660px;\n      height: 78vh;\n    }\n    .bot-header {\n      padding: 12px 16px;\n      background: linear-gradient(135deg, rgba(79, 140, 255, 0.16), rgba(168, 85, 247, 0.14));\n      border-bottom: 1px solid var(--border);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 8px;\n    }\n    .bot-header-title {\n      font-weight: 700;\n      font-size: 0.94rem;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .bot-header-actions { display: flex; gap: 6px; }\n    .bot-header-actions button { padding: 4px 9px; font-size: 0.76rem; }\n    .bot-body {\n      flex: 1;\n      display: flex;\n      flex-direction: column;\n      padding: 12px 14px;\n      overflow: hidden;\n    }\n    .bot-messages {\n      flex: 1;\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n      overflow-y: auto;\n      padding-right: 4px;\n    }\n    .bot-msg {\n      background: var(--surface-2);\n      border: 1px solid var(--border);\n      border-radius: 10px;\n      padding: 10px 12px;\n      font-size: 0.85rem;\n    }\n    .bot-msg.user {\n      background: rgba(79, 140, 255, 0.18);\n      border-color: rgba(79, 140, 255, 0.45);\n      align-self: flex-end;\n      max-width: 82%;\n    }\n    .bot-headline { font-weight: 700; font-size: 0.92rem; margin-bottom: 5px; color: #fff; }\n    .bot-points { margin: 6px 0 4px; padding-left: 18px; }\n    .bot-points li { margin-bottom: 3px; }\n    .bot-meta { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 8px; font-size: 0.72rem; color: var(--muted); }\n    .bot-chips-wrap {\n      padding: 8px 14px 4px;\n      border-top: 1px solid var(--border);\n      background: rgba(11, 16, 32, 0.4);\n    }\n    .bot-chips-label {\n      font-size: 0.7rem;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      color: var(--muted);\n      margin-bottom: 5px;\n    }\n    .bot-chips {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 6px;\n    }\n    .chip {\n      background: var(--surface-2);\n      border: 1px solid var(--border);\n      border-radius: 99px;\n      padding: 4px 10px;\n      font-size: 0.75rem;\n      color: var(--muted);\n      cursor: pointer;\n      max-width: 100%;\n      white-space: nowrap;\n      overflow: hidden;\n      text-overflow: ellipsis;\n    }\n    .chip:hover { color: var(--text); border-color: var(--accent); }\n    .chip.frequent {\n      border-color: rgba(245, 158, 11, 0.55);\n      background: rgba(245, 158, 11, 0.12);\n      color: #fde68a;\n    }\n    .bot-footer {\n      padding: 10px 14px 12px;\n      display: flex;\n      gap: 8px;\n      background: var(--surface);\n      border-top: 1px solid var(--border);\n    }\n    .bot-footer input { flex: 1; }\n\n    /* Accounts & Keys Modal */\n    .modal.modal-wide { max-width: 880px; }\n    .form-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));\n      gap: 10px;\n      margin-bottom: 12px;\n    }\n    .form-field { display: flex; flex-direction: column; gap: 4px; font-size: 0.78rem; color: var(--muted); }\n    .form-field input, .form-field select { width: 100%; }\n    .key-reveal {\n      background: rgba(34, 197, 94, 0.12);\n      border: 1px solid rgba(34, 197, 94, 0.45);\n      border-radius: 10px;\n      padding: 12px 14px;\n      margin-bottom: 14px;\n      font-size: 0.84rem;\n    }\n    .key-reveal code {\n      display: inline-block;\n      background: var(--bg);\n      border: 1px solid var(--border);\n      padding: 4px 8px;\n      border-radius: 6px;\n      font-size: 0.82rem;\n      color: #86efac;\n      word-break: break-all;\n    }\n    .org-pill {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      background: rgba(79, 140, 255, 0.14);\n      border: 1px solid rgba(79, 140, 255, 0.4);\n      color: #bfdbfe;\n      padding: 6px 10px;\n      border-radius: 8px;\n      font-size: 0.82rem;\n      font-weight: 600;\n    }\n    button.danger { border-color: rgba(239, 68, 68, 0.45); color: #fca5a5; }\n    button.danger:hover { border-color: var(--red); background: rgba(239, 68, 68, 0.15); }\n    button.sm { padding: 4px 9px; font-size: 0.76rem; }\n  </style>\n</head>\n<body>\n  <header>\n    <div class=\"brand\">\n      <span class=\"dot\"></span>\n      <span>SmartFlow Intelligence</span>\n    </div>\n    <div class=\"controls\">\n      <select id=\"accountSwitcher\" style=\"display:none;\" title=\"Switch Smartflo Organization\"></select>\n      <span id=\"singleAccountPill\" class=\"org-pill\" style=\"display:none;\"></span>\n      <input type=\"date\" id=\"datePicker\" />\n      <button id=\"refreshBtn\" class=\"primary\">Refresh</button>\n      <button id=\"syncBtn\">Sync Day</button>\n      <button id=\"enqueueBtn\">Process Pending (All)</button>\n      <button id=\"accountsBtn\" style=\"display:none;\" title=\"Manage Organizations &amp; Claude API Keys\">Accounts &amp; Keys</button>\n      <button id=\"keyBtn\" title=\"Change API Key\">API Key</button>\n    </div>\n  </header>\n\n  <main id=\"appRoot\">\n    <div id=\"authScreen\" class=\"auth-box\" style=\"display:none;\">\n      <h2 style=\"margin-bottom:6px;\">Connect to SmartFlow API</h2>\n      <div class=\"muted\">Enter your <code>MCP_API_KEY</code> from <code>.env</code>. It is stored only in your browser's localStorage.</div>\n      <input type=\"password\" id=\"apiKeyInput\" placeholder=\"Paste MCP_API_KEY...\" />\n      <button id=\"saveKeyBtn\" class=\"primary\">Unlock Dashboard</button>\n    </div>\n\n    <div id=\"dashboardContent\" style=\"display:none;\">\n      <div id=\"statusBanner\" class=\"banner\">\n        <span id=\"statusText\">Loading SmartFlow analytics...</span>\n        <span id=\"providerText\"></span>\n      </div>\n\n      <section class=\"grid-kpi\">\n        <div class=\"card kpi-card\" id=\"cardTotal\" title=\"Click to show all calls\">\n          <div class=\"kpi-label\">Total Calls</div>\n          <div class=\"kpi-value\" id=\"kpiTotal\">—</div>\n          <div class=\"kpi-sub\" id=\"kpiUnique\">Unique leads: —</div>\n        </div>\n        <div class=\"card kpi-card\" id=\"cardAnswered\" title=\"Click to filter answered calls\">\n          <div class=\"kpi-label\">Answered</div>\n          <div class=\"kpi-value\" id=\"kpiAnswered\" style=\"color:var(--green)\">—</div>\n          <div class=\"kpi-sub\" id=\"kpiConnRate\">Connection rate: —</div>\n        </div>\n        <div class=\"card kpi-card\" id=\"cardMissed\" title=\"Click to filter missed calls\">\n          <div class=\"kpi-label\">Missed / Failed</div>\n          <div class=\"kpi-value\" id=\"kpiMissed\" style=\"color:var(--amber)\">—</div>\n          <div class=\"kpi-sub\" id=\"kpiAvgTalk\">Avg talk time: —</div>\n        </div>\n        <div class=\"card kpi-card\" id=\"cardFollowups\" title=\"Click to filter calls with pending follow-ups\">\n          <div class=\"kpi-label\">Follow-ups Pending</div>\n          <div class=\"kpi-value\" id=\"kpiFollowups\">—</div>\n          <div class=\"kpi-sub\" id=\"kpiHot\">Interested / Hot: —</div>\n        </div>\n        <div class=\"card kpi-card\" id=\"cardCoverage\" title=\"Click to filter answered calls\">\n          <div class=\"kpi-label\">Analysis Coverage</div>\n          <div class=\"kpi-value\" id=\"kpiCoverage\">—%</div>\n          <div class=\"progress\"><div id=\"coverageBar\" style=\"width:0%\"></div></div>\n          <div class=\"kpi-sub\" id=\"kpiCoverageSub\">— / — answered calls</div>\n        </div>\n      </section>\n\n      <section id=\"queueSection\" class=\"card\" style=\"margin-bottom:20px;display:none;\">\n        <h2>\n          <span>Background Queues (Redis + BullMQ)</span>\n          <span class=\"muted\" id=\"lastSyncText\">Last sync: —</span>\n        </h2>\n        <div class=\"queue-grid\" id=\"queueGrid\"></div>\n      </section>\n\n      <section class=\"grid-2\">\n        <div class=\"card\">\n          <h2>\n            <span>Telecaller Performance</span>\n            <span class=\"muted\">Color-coded by connection rate (🟢 ≥65% · 🟡 40–64% · 🔴 &lt;40%)</span>\n          </h2>\n          <div id=\"agentsGrid\" class=\"agent-grid\"></div>\n        </div>\n\n        <div class=\"card\">\n          <h2>\n            <span>Call Outcome Breakdown</span>\n            <span class=\"muted\" id=\"outcomeMeta\">Analyzed calls</span>\n          </h2>\n          <div id=\"outcomeChartBox\" class=\"outcome-chart-wrap\">\n            <div class=\"muted\">Loading outcome graph...</div>\n          </div>\n          <hr style=\"border:none;border-top:1px solid var(--border);margin:14px 0;\" />\n          <div id=\"funnelBox\" class=\"muted\" style=\"font-size:0.82rem;\">Loading funnel...</div>\n        </div>\n      </section>\n\n      <section id=\"callsExplorerSection\" class=\"card\">\n        <h2>\n          <span>Calls Explorer</span>\n          <div class=\"controls\">\n            <select id=\"departmentFilter\">\n              <option value=\"\">All branches</option>\n            </select>\n            <select id=\"statusFilter\">\n              <option value=\"\">All statuses</option>\n              <option value=\"answered\">Answered</option>\n              <option value=\"missed\">Missed</option>\n              <option value=\"failed\">Failed</option>\n            </select>\n            <input type=\"text\" id=\"searchInput\" placeholder=\"Search transcript / disposition...\" />\n            <button id=\"searchBtn\">Search</button>\n          </div>\n        </h2>\n        <div id=\"activeFilterBar\" class=\"active-filter-bar\"></div>\n        <div style=\"overflow-x:auto;\">\n          <table>\n            <thead>\n              <tr>\n                <th>Time (IST)</th>\n                <th>Branch</th>\n                <th>Agent</th>\n                <th>Lead</th>\n                <th>Dir</th>\n                <th>Status</th>\n                <th>Talk</th>\n                <th>Outcome</th>\n                <th>Temp</th>\n                <th>QA</th>\n              </tr>\n            </thead>\n            <tbody id=\"callsBody\"></tbody>\n          </table>\n        </div>\n      </section>\n    </div>\n  </main>\n\n  <div id=\"callModal\" class=\"modal-backdrop\">\n    <div class=\"modal\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;\">\n        <h2 style=\"margin:0;\">Call Intelligence Detail</h2>\n        <button id=\"closeModalBtn\">Close</button>\n      </div>\n      <div id=\"modalBody\" class=\"muted\">Loading...</div>\n    </div>\n  </div>\n\n  <!-- Admin Multi-Account & Claude API Keys Modal -->\n  <div id=\"accountsModal\" class=\"modal-backdrop\">\n    <div class=\"modal modal-wide\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;\">\n        <div>\n          <h2 style=\"margin:0;\">Organizations &amp; Claude MCP Keys</h2>\n          <div class=\"muted\" style=\"margin-top:2px;\">MCP URL for Claude: <code id=\"mcpUrlDisplay\"></code></div>\n        </div>\n        <button id=\"closeAccountsModalBtn\">Close</button>\n      </div>\n\n      <div id=\"accountsMsg\" class=\"banner\" style=\"display:none;margin-bottom:12px;\"></div>\n      <div id=\"newKeyReveal\" class=\"key-reveal\" style=\"display:none;\"></div>\n\n      <div id=\"editOrgCard\" class=\"card\" style=\"display:none;margin-bottom:14px;background:var(--surface-2);border-color:var(--accent);\">\n        <h2 style=\"font-size:0.92rem;margin-bottom:10px;\">\n          <span>Edit Organization</span>\n          <button id=\"cancelEditOrgBtn\" class=\"sm\">Cancel</button>\n        </h2>\n        <input type=\"hidden\" id=\"editOrgId\" />\n        <input type=\"hidden\" id=\"editOrgOldSlug\" />\n        <div class=\"form-grid\">\n          <div class=\"form-field\">\n            <label>Organization Name *</label>\n            <input type=\"text\" id=\"editOrgName\" placeholder=\"Organization name\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Slug</label>\n            <input type=\"text\" id=\"editOrgSlug\" placeholder=\"org-slug\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Timezone</label>\n            <input type=\"text\" id=\"editOrgTz\" value=\"Asia/Kolkata\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Smartflo Portal API Token</label>\n            <div style=\"display:flex;gap:6px;\">\n              <input type=\"password\" id=\"editOrgApiKey\" placeholder=\"Paste Smartflo API token...\" style=\"flex:1;\" />\n              <button type=\"button\" id=\"toggleEditApiKeyBtn\" class=\"sm\">Show</button>\n            </div>\n          </div>\n          <div class=\"form-field\">\n            <label>Smartflo Email (optional)</label>\n            <input type=\"email\" id=\"editOrgEmail\" placeholder=\"user@org.com\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Status</label>\n            <select id=\"editOrgActive\">\n              <option value=\"true\">Active</option>\n              <option value=\"false\">Inactive</option>\n            </select>\n          </div>\n        </div>\n        <div style=\"display:flex;justify-content:flex-end;gap:8px;\">\n          <button id=\"saveEditOrgBtn\" class=\"primary\">Save Changes</button>\n        </div>\n      </div>\n\n      <div class=\"card\" style=\"margin-bottom:14px;background:var(--surface-2);\">\n        <h2 style=\"font-size:0.92rem;margin-bottom:10px;\">\n          <span>Add Smartflo Organization</span>\n          <span class=\"muted\">Credentials are encrypted with AES-256-GCM</span>\n        </h2>\n        <div class=\"form-grid\">\n          <div class=\"form-field\">\n            <label>Organization Name *</label>\n            <input type=\"text\" id=\"newOrgName\" placeholder=\"e.g. Acme Clinic\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Slug (used in Claude &amp; webhooks)</label>\n            <input type=\"text\" id=\"newOrgSlug\" placeholder=\"e.g. acme-clinic\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Timezone</label>\n            <input type=\"text\" id=\"newOrgTz\" value=\"Asia/Kolkata\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Smartflo Portal API Token</label>\n            <input type=\"password\" id=\"newOrgApiKey\" placeholder=\"Paste Smartflo API token...\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Or Smartflo Email (optional)</label>\n            <input type=\"email\" id=\"newOrgEmail\" placeholder=\"user@org.com\" />\n          </div>\n          <div class=\"form-field\">\n            <label>Or Smartflo Password (optional)</label>\n            <input type=\"password\" id=\"newOrgPassword\" placeholder=\"Password\" />\n          </div>\n        </div>\n        <div style=\"display:flex;justify-content:flex-end;gap:8px;\">\n          <button id=\"createOrgBtn\" class=\"primary\">Add Organization</button>\n        </div>\n      </div>\n\n      <div class=\"card\" style=\"margin-bottom:14px;background:var(--surface-2);\">\n        <h2 style=\"font-size:0.92rem;margin-bottom:10px;\">\n          <span>Connected Organizations</span>\n          <span class=\"muted\" id=\"orgsCountLabel\">0 organizations</span>\n        </h2>\n        <div style=\"overflow-x:auto;\">\n          <table>\n            <thead>\n              <tr>\n                <th>Organization</th>\n                <th>Slug</th>\n                <th>Smartflo Auth</th>\n                <th>Status</th>\n                <th>Actions</th>\n              </tr>\n            </thead>\n            <tbody id=\"orgsTableBody\"></tbody>\n          </table>\n        </div>\n      </div>\n\n      <div class=\"card\" style=\"background:var(--surface-2);\">\n        <h2 style=\"font-size:0.92rem;margin-bottom:10px;\">\n          <span>Issued Claude API Keys</span>\n          <button id=\"issueAdminKeyBtn\" class=\"sm\">+ Issue Admin Key (All Orgs)</button>\n        </h2>\n        <div style=\"overflow-x:auto;\">\n          <table>\n            <thead>\n              <tr>\n                <th>Name</th>\n                <th>Role</th>\n                <th>Prefix</th>\n                <th>Last Used</th>\n                <th>Status</th>\n                <th>Action</th>\n              </tr>\n            </thead>\n            <tbody id=\"apiKeysTableBody\"></tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Floating AI Assistant Bot (Bottom Right) -->\n  <button id=\"botFab\" class=\"bot-fab\" title=\"Open SmartFlow AI Assistant\">\n    <span>✦</span>\n    <span>Ask SmartFlow AI</span>\n  </button>\n\n  <div id=\"botPanel\" class=\"bot-panel\">\n    <div class=\"bot-header\">\n      <div class=\"bot-header-title\">\n        <span style=\"color:#93c5fd;\">✦</span>\n        <span>SmartFlow AI Assistant</span>\n      </div>\n      <div class=\"bot-header-actions\">\n        <button id=\"botExpandBtn\" title=\"Expand / Compact\">Expand</button>\n        <button id=\"botCloseBtn\" title=\"Close\">✕</button>\n      </div>\n    </div>\n    <div class=\"bot-body\">\n      <div id=\"botMessages\" class=\"bot-messages\">\n        <div class=\"bot-msg muted\">\n          Ask any question about calls, branches, telecallers, follow-ups, or objections. Answers are backed by deterministic MCP SQL tools.\n        </div>\n      </div>\n    </div>\n    <div class=\"bot-chips-wrap\">\n      <div id=\"frequentWrap\" style=\"display:none;margin-bottom:8px;\">\n        <div class=\"bot-chips-label\">★ Frequently Asked</div>\n        <div id=\"frequentChips\" class=\"bot-chips\"></div>\n      </div>\n      <div class=\"bot-chips-label\">Quick Questions</div>\n      <div id=\"starterChips\" class=\"bot-chips\">\n        <button class=\"chip\" data-q=\"Give me a simple breakdown of today's call performance by branch\">Branch breakdown</button>\n        <button class=\"chip\" data-q=\"Which telecaller handled the most unique leads and highest connection rate today?\">Top telecaller</button>\n        <button class=\"chip\" data-q=\"What follow-ups are pending or missed opportunities today?\">Pending follow-ups</button>\n        <button class=\"chip\" data-q=\"What are the common customer objections and calls needing review?\">Objections &amp; QA</button>\n      </div>\n    </div>\n    <div class=\"bot-footer\">\n      <input type=\"text\" id=\"botInput\" placeholder=\"Ask about calls, branches, agents...\" />\n      <button id=\"botAskBtn\" class=\"primary\">Ask</button>\n    </div>\n  </div>\n\n  <script>\n    const STORAGE_KEY = \"smartflow_mcp_api_key\";\n    const ACCOUNT_STORAGE_KEY = \"smartflow_selected_account\";\n    let currentUserRole = \"tenant\";\n    let knownAccounts = [];\n\n    function getApiKey() {\n      return localStorage.getItem(STORAGE_KEY) || \"\";\n    }\n\n    function getSelectedAccount() {\n      return localStorage.getItem(ACCOUNT_STORAGE_KEY) || \"\";\n    }\n\n    function setSelectedAccount(slug) {\n      if (slug) localStorage.setItem(ACCOUNT_STORAGE_KEY, slug);\n      else localStorage.removeItem(ACCOUNT_STORAGE_KEY);\n    }\n\n    function todayIstYmd() {\n      const parts = new Intl.DateTimeFormat(\"en-CA\", {\n        timeZone: \"Asia/Kolkata\",\n        year: \"numeric\",\n        month: \"2-digit\",\n        day: \"2-digit\",\n      }).formatToParts(new Date());\n      const g = (t) => parts.find((p) => p.type === t)?.value || \"00\";\n      return `${g(\"year\")}-${g(\"month\")}-${g(\"day\")}`;\n    }\n\n    async function apiFetch(path, options = {}) {\n      const selectedAcc = getSelectedAccount();\n      const headers = {\n        ...(options.body !== undefined ? { \"Content-Type\": \"application/json\" } : {}),\n        ...(getApiKey() ? { Authorization: `Bearer ${getApiKey()}` } : {}),\n        ...(selectedAcc && !options.skipAccountHeader ? { \"x-account\": selectedAcc } : {}),\n        ...(options.headers || {}),\n      };\n      const res = await fetch(path, { ...options, headers });\n      if (res.status === 401) {\n        showAuthScreen(\"Unauthorized — please enter your valid API key.\");\n        throw new Error(\"Unauthorized\");\n      }\n      if (!res.ok) {\n        const err = await res.json().catch(() => ({ error: res.statusText }));\n        throw new Error(err.error || `HTTP ${res.status}`);\n      }\n      return res.json();\n    }\n\n    async function loadAccountsContext() {\n      const res = await apiFetch(\"/api/v1/accounts\", { skipAccountHeader: true });\n      currentUserRole = res.role || \"tenant\";\n      knownAccounts = res.accounts || [];\n      const activeAccounts = knownAccounts.filter((a) => a.active);\n\n      const switcher = document.getElementById(\"accountSwitcher\");\n      const pill = document.getElementById(\"singleAccountPill\");\n      const accountsBtn = document.getElementById(\"accountsBtn\");\n\n      if (currentUserRole === \"admin\") {\n        accountsBtn.style.display = \"inline-block\";\n        pill.style.display = \"none\";\n        switcher.style.display = activeAccounts.length > 0 ? \"inline-block\" : \"none\";\n\n        const current = getSelectedAccount();\n        const validCurrent = activeAccounts.find((a) => a.slug === current || a.id === current);\n        const chosen = validCurrent ? (validCurrent.slug || validCurrent.id) : (activeAccounts[0]?.slug || activeAccounts[0]?.id || \"\");\n        setSelectedAccount(chosen);\n\n        switcher.innerHTML = activeAccounts\n          .map((a) => {\n            const val = a.slug || a.id;\n            return `<option value=\"${escapeHtml(val)}\">${escapeHtml(a.name)}</option>`;\n          })\n          .join(\"\");\n        if (chosen) switcher.value = chosen;\n      } else {\n        accountsBtn.style.display = \"none\";\n        switcher.style.display = \"none\";\n        const own = activeAccounts[0];\n        if (own) {\n          setSelectedAccount(own.slug || own.id);\n          pill.textContent = `Org: ${own.name}`;\n          pill.style.display = \"inline-flex\";\n        }\n      }\n    }\n\n    function showAuthScreen(msg) {\n      document.getElementById(\"authScreen\").style.display = \"block\";\n      document.getElementById(\"dashboardContent\").style.display = \"none\";\n      if (msg) setBanner(msg, true);\n    }\n\n    function showDashboard() {\n      document.getElementById(\"authScreen\").style.display = \"none\";\n      document.getElementById(\"dashboardContent\").style.display = \"block\";\n    }\n\n    function setBanner(text, isError = false) {\n      const el = document.getElementById(\"statusBanner\");\n      el.className = isError ? \"banner error\" : \"banner\";\n      document.getElementById(\"statusText\").textContent = text;\n    }\n\n    function fmtSeconds(sec) {\n      if (sec == null) return \"—\";\n      const m = Math.floor(sec / 60);\n      const s = sec % 60;\n      return m > 0 ? `${m}m ${s}s` : `${s}s`;\n    }\n\n    function fmtIstTime(iso) {\n      return new Intl.DateTimeFormat(\"en-IN\", {\n        timeZone: \"Asia/Kolkata\",\n        hour: \"2-digit\",\n        minute: \"2-digit\",\n        second: \"2-digit\",\n        hour12: true,\n      }).format(new Date(iso));\n    }\n\n    function statusBadge(status) {\n      const map = { answered: \"green\", missed: \"amber\", failed: \"red\" };\n      return `<span class=\"badge ${map[status] || \"gray\"}\">${status || \"—\"}</span>`;\n    }\n\n    function tempBadge(temp) {\n      if (!temp) return `<span class=\"muted\">—</span>`;\n      const map = { hot: \"red\", warm: \"amber\", cold: \"blue\" };\n      return `<span class=\"badge ${map[temp] || \"gray\"}\">${temp}</span>`;\n    }\n\n    function getSelectedDayRange(dateYmd) {\n      return {\n        from: `${dateYmd}T00:00:00+05:30`,\n        to: `${dateYmd}T23:59:59+05:30`,\n      };\n    }\n\n    // Interactive cross-filter state (click any KPI, Agent card, or Outcome row)\n    const activeCrossFilter = {\n      agentId: \"\",\n      agentName: \"\",\n      outcome: \"\",\n      hasFollowup: false,\n      cardId: \"\",\n    };\n\n    function clearCrossFilter(reload = true) {\n      activeCrossFilter.agentId = \"\";\n      activeCrossFilter.agentName = \"\";\n      activeCrossFilter.outcome = \"\";\n      activeCrossFilter.hasFollowup = false;\n      activeCrossFilter.cardId = \"\";\n      document.getElementById(\"statusFilter\").value = \"\";\n      if (reload) loadDashboard();\n    }\n\n    function renderActiveFilterBar() {\n      const bar = document.getElementById(\"activeFilterBar\");\n      const pills = [];\n      if (activeCrossFilter.agentName) {\n        pills.push(`<span class=\"filter-pill\">Agent: ${escapeHtml(activeCrossFilter.agentName)} <button data-clear=\"agent\">✕</button></span>`);\n      }\n      if (activeCrossFilter.outcome) {\n        pills.push(`<span class=\"filter-pill\">Outcome: ${escapeHtml(activeCrossFilter.outcome.replaceAll(\"_\", \" \"))} <button data-clear=\"outcome\">✕</button></span>`);\n      }\n      if (activeCrossFilter.hasFollowup) {\n        pills.push(`<span class=\"filter-pill\">Pending Follow-ups <button data-clear=\"followup\">✕</button></span>`);\n      }\n      const statusVal = document.getElementById(\"statusFilter\").value;\n      if (statusVal) {\n        pills.push(`<span class=\"filter-pill\">Status: ${escapeHtml(statusVal)} <button data-clear=\"status\">✕</button></span>`);\n      }\n\n      // Highlight active KPI card\n      document.querySelectorAll(\".kpi-card\").forEach((el) => el.classList.remove(\"active-filter\"));\n      if (activeCrossFilter.cardId) {\n        document.getElementById(activeCrossFilter.cardId)?.classList.add(\"active-filter\");\n      }\n\n      if (!pills.length) {\n        bar.classList.remove(\"show\");\n        bar.innerHTML = \"\";\n        return;\n      }\n      bar.classList.add(\"show\");\n      bar.innerHTML = `<span class=\"muted\">Active filter:</span> ${pills.join(\"\")} <button id=\"clearAllFiltersBtn\" style=\"padding:3px 9px;font-size:0.75rem;\">Clear all</button>`;\n\n      bar.querySelectorAll(\"button[data-clear]\").forEach((b) => {\n        b.addEventListener(\"click\", () => {\n          const what = b.dataset.clear;\n          if (what === \"agent\") { activeCrossFilter.agentId = \"\"; activeCrossFilter.agentName = \"\"; }\n          if (what === \"outcome\") { activeCrossFilter.outcome = \"\"; }\n          if (what === \"followup\") { activeCrossFilter.hasFollowup = false; activeCrossFilter.cardId = \"\"; }\n          if (what === \"status\") { document.getElementById(\"statusFilter\").value = \"\"; activeCrossFilter.cardId = \"\"; }\n          loadDashboard();\n        });\n      });\n      document.getElementById(\"clearAllFiltersBtn\")?.addEventListener(\"click\", () => clearCrossFilter(true));\n    }\n\n    function scrollToExplorer() {\n      document.getElementById(\"callsExplorerSection\")?.scrollIntoView({ behavior: \"smooth\", block: \"nearest\" });\n    }\n\n    async function loadDashboard() {\n      const dateYmd = document.getElementById(\"datePicker\").value || todayIstYmd();\n      const { from, to } = getSelectedDayRange(dateYmd);\n      const department = document.getElementById(\"departmentFilter\").value;\n      const status = document.getElementById(\"statusFilter\").value;\n      const searchText = document.getElementById(\"searchInput\").value.trim();\n\n      renderActiveFilterBar();\n      setBanner(`Refreshing data for ${dateYmd} (Asia/Kolkata)...`);\n      try {\n        const callParams = new URLSearchParams({ from, to, limit: \"100\" });\n        if (department) callParams.set(\"department\", department);\n        if (status) callParams.set(\"status\", status);\n        if (activeCrossFilter.agentId) callParams.set(\"agentId\", activeCrossFilter.agentId);\n        if (activeCrossFilter.outcome) callParams.set(\"outcome\", activeCrossFilter.outcome);\n        if (activeCrossFilter.hasFollowup) callParams.set(\"hasFollowup\", \"true\");\n        if (searchText) callParams.set(\"searchText\", searchText);\n\n        const [daily, agents, funnel, calls, departmentsRes, queues, providers] = await Promise.all([\n          apiFetch(`/api/v1/reports/daily?date=${encodeURIComponent(dateYmd)}`),\n          apiFetch(`/api/v1/reports/agents?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`),\n          apiFetch(`/api/v1/reports/conversions?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`),\n          apiFetch(`/api/v1/calls?${callParams.toString()}`),\n          apiFetch(`/api/v1/departments?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`),\n          apiFetch(`/api/v1/queues/status`),\n          apiFetch(`/api/v1/providers`),\n        ]);\n\n        showDashboard();\n\n        // Populate branch/department filter while preserving current selection\n        const deptSelect = document.getElementById(\"departmentFilter\");\n        const prevDept = deptSelect.value;\n        deptSelect.innerHTML =\n          `<option value=\"\">All branches</option>` +\n          (departmentsRes.departments || [])\n            .map((d) => `<option value=\"${escapeHtml(d.value)}\">${escapeHtml(d.label)} (${d.callCount})</option>`)\n            .join(\"\");\n        deptSelect.value = prevDept;\n\n        // KPIs\n        const act = daily.callActivity;\n        const comp = daily.completeness;\n        const sig = daily.leadSignals;\n\n        document.getElementById(\"kpiTotal\").textContent = act.totalCalls;\n        document.getElementById(\"kpiUnique\").textContent = `Unique leads: ${act.uniqueLeads}`;\n        document.getElementById(\"kpiAnswered\").textContent = act.answeredCalls;\n        document.getElementById(\"kpiConnRate\").textContent = `Connection rate: ${act.connectionRatePct}%`;\n        document.getElementById(\"kpiMissed\").textContent = `${act.missedCalls} / ${act.failedCalls}`;\n        document.getElementById(\"kpiAvgTalk\").textContent = `Avg talk: ${fmtSeconds(act.avgTalkDurationSeconds)}`;\n        document.getElementById(\"kpiFollowups\").textContent = sig.pendingFollowups;\n        document.getElementById(\"kpiHot\").textContent = `Interested: ${sig.interestedCalls} · Hot: ${sig.hotLeadCalls}`;\n        const missingAudioCount = Math.max(0, comp.answeredCalls - comp.withRecording);\n        document.getElementById(\"kpiCoverage\").textContent = `${comp.analysisCompletenessPct}%`;\n        document.getElementById(\"coverageBar\").style.width = `${comp.analysisCompletenessPct}%`;\n        document.getElementById(\"kpiCoverageSub\").textContent = missingAudioCount > 0\n          ? `${comp.withAnalysis} / ${comp.answeredCalls} analyzed (${missingAudioCount} no audio)`\n          : `${comp.withAnalysis} / ${comp.answeredCalls} answered analyzed`;\n        document.getElementById(\"lastSyncText\").textContent = comp.lastSyncAt\n          ? `Last sync (${comp.lastSyncStatus}): ${new Date(comp.lastSyncAt).toLocaleString(\"en-IN\", { timeZone: \"Asia/Kolkata\" })} IST`\n          : \"Never synced\";\n\n        document.getElementById(\"providerText\").textContent =\n          `STT: ${providers.transcription.provider}/${providers.transcription.model} · LLM: ${providers.analysis.provider}/${providers.analysis.model}`;\n\n        // Queues (only show BullMQ card when Redis worker mode is active; hide empty boxes on Vercel serverless)\n        const qSection = document.getElementById(\"queueSection\");\n        const queueMode = queues.mode || \"bullmq\";\n        const queueData = queues.queues || queues;\n        if (queueMode === \"serverless\") {\n          qSection.style.display = \"none\";\n        } else {\n          qSection.style.display = \"block\";\n          const qGrid = document.getElementById(\"queueGrid\");\n          qGrid.innerHTML = Object.entries(queueData)\n            .map(\n              ([name, c]) => `\n              <div class=\"q-box\">\n                <div class=\"q-title\">${name}</div>\n                <div class=\"q-nums\">\n                  <span>wait: <b>${c.waiting ?? 0}</b></span>\n                  <span>active: <b style=\"color:var(--accent)\">${c.active ?? 0}</b></span>\n                  <span>done: <b style=\"color:var(--green)\">${c.completed ?? 0}</b></span>\n                  <span>fail: <b style=\"color:${(c.failed ?? 0) > 0 ? \"var(--red)\" : \"inherit\"}\">${c.failed ?? 0}</b></span>\n                </div>\n              </div>`\n            )\n            .join(\"\");\n        }\n\n        // Compact Color-Coded Telecaller Performance Cards\n        const agentsGrid = document.getElementById(\"agentsGrid\");\n        const activeAgents = agents.agents.filter((a) => a.totalCalls > 0);\n        const idleAgents = agents.agents.filter((a) => a.totalCalls === 0);\n        const orderedAgents = [...activeAgents, ...idleAgents];\n        agentsGrid.innerHTML = orderedAgents.length\n          ? orderedAgents\n              .map((a) => {\n                const tier =\n                  a.totalCalls === 0\n                    ? \"tier-idle\"\n                    : a.connectionRatePct >= 65\n                      ? \"tier-high\"\n                      : a.connectionRatePct >= 40\n                        ? \"tier-mid\"\n                        : \"tier-low\";\n                const barColor =\n                  tier === \"tier-high\"\n                    ? \"var(--green)\"\n                    : tier === \"tier-mid\"\n                      ? \"var(--amber)\"\n                      : tier === \"tier-low\"\n                        ? \"var(--red)\"\n                        : \"#475569\";\n                const pillCls =\n                  tier === \"tier-high\"\n                    ? \"green\"\n                    : tier === \"tier-mid\"\n                      ? \"amber\"\n                      : tier === \"tier-low\"\n                        ? \"red\"\n                        : \"gray\";\n                const isSelected = activeCrossFilter.agentId === a.agentId;\n                return `\n                  <div class=\"agent-card ${tier} ${isSelected ? \"active-filter\" : \"\"}\" data-agent-id=\"${a.agentId}\" data-agent-name=\"${escapeHtml(a.name)}\" title=\"Click to filter calls by ${escapeHtml(a.name)}\">\n                    <div class=\"agent-top\">\n                      <span class=\"agent-name\" title=\"${escapeHtml(a.name)}\">${escapeHtml(a.name)}</span>\n                      <span class=\"badge ${pillCls}\">${a.totalCalls ? a.connectionRatePct + \"%\" : \"Idle\"}</span>\n                    </div>\n                    <div class=\"mini-bar\"><div style=\"width:${a.connectionRatePct}%;background:${barColor};\"></div></div>\n                    <div class=\"agent-stats\">\n                      <span>${a.connectedCalls}/${a.totalCalls} ans</span>\n                      <span>${a.uniqueLeads} leads</span>\n                      <span>${fmtSeconds(a.avgTalkDurationSeconds)}</span>\n                    </div>\n                    <div class=\"agent-stats\">\n                      <span>QA: ${a.avgQualityScore != null ? `<b style=\"color:var(--text)\">${a.avgQualityScore}/100</b>` : \"—\"}</span>\n                      <span>${a.analyzedCalls} analyzed</span>\n                    </div>\n                  </div>`;\n              })\n              .join(\"\")\n          : `<div class=\"muted\">No agent activity for this date.</div>`;\n\n        agentsGrid.querySelectorAll(\".agent-card[data-agent-id]\").forEach((card) => {\n          card.addEventListener(\"click\", () => {\n            const id = card.dataset.agentId;\n            if (activeCrossFilter.agentId === id) {\n              activeCrossFilter.agentId = \"\";\n              activeCrossFilter.agentName = \"\";\n            } else {\n              activeCrossFilter.agentId = id;\n              activeCrossFilter.agentName = card.dataset.agentName;\n            }\n            loadDashboard().then(scrollToExplorer);\n          });\n        });\n\n        // Outcome Breakdown SVG Donut + Bar Graph\n        renderOutcomeChart(daily.outcomeBreakdown || []);\n\n        // Compact Funnel summary\n        const reach = funnel.leadReach;\n        document.getElementById(\"funnelBox\").innerHTML = `\n          <div style=\"display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;\">\n            <span>Attempted leads: <b style=\"color:var(--text)\">${reach.attemptedUniqueLeads}</b></span>\n            <span>Connected leads: <b style=\"color:var(--green)\">${reach.connectedUniqueLeads} (${reach.leadContactRatePct}%)</b></span>\n          </div>\n        `;\n\n        // Calls table\n        document.getElementById(\"callsBody\").innerHTML = calls.calls.length\n          ? calls.calls\n              .map(\n                (c) => `\n              <tr class=\"clickable\" data-call-id=\"${c.callId}\">\n                <td>${fmtIstTime(c.startedAt)}</td>\n                <td>${c.department ? `<span class=\"badge gray\">${escapeHtml(c.department)}</span>` : `<span class=\"muted\">—</span>`}</td>\n                <td>${escapeHtml(c.agentName)}</td>\n                <td>${c.leadName ? `<b>${escapeHtml(c.leadName)}</b> <code class=\"muted\">${escapeHtml(c.leadPhoneMasked)}</code>` : `<code>${escapeHtml(c.leadPhoneMasked)}</code>`}</td>\n                <td>${escapeHtml(c.direction || \"—\")}</td>\n                <td>${statusBadge(c.status)}</td>\n                <td>${fmtSeconds(c.answeredSeconds ?? c.durationSeconds)}</td>\n                <td>${c.callOutcome ? escapeHtml(c.callOutcome.replaceAll(\"_\", \" \")) : `<span class=\"muted\">—</span>`}</td>\n                <td>${tempBadge(c.leadTemperature)}</td>\n                <td>${c.qualityScore != null ? `<b>${c.qualityScore}</b>` : `<span class=\"muted\">—</span>`}</td>\n              </tr>`\n              )\n              .join(\"\")\n          : `<tr><td colspan=\"10\" class=\"muted\">No calls match your filter.</td></tr>`;\n\n        document.querySelectorAll(\"#callsBody tr[data-call-id]\").forEach((row) => {\n          row.addEventListener(\"click\", () => openCallModal(row.dataset.callId));\n        });\n\n        setBanner(`Showing ${dateYmd} (Asia/Kolkata) · ${act.totalCalls} calls · ${comp.analysisCompletenessPct}% analyzed`);\n      } catch (err) {\n        if (err.message !== \"Unauthorized\") {\n          setBanner(`Error: ${err.message}`, true);\n        }\n      }\n    }\n\n    async function openCallModal(callId) {\n      const modal = document.getElementById(\"callModal\");\n      const body = document.getElementById(\"modalBody\");\n      modal.classList.add(\"open\");\n      body.innerHTML = \"Loading call details...\";\n\n      try {\n        const detail = await apiFetch(`/api/v1/calls/${callId}`);\n        const c = detail.call;\n        const a = detail.latestAnalysis;\n        const aj = a?.analysisJson || null;\n\n        let html = `\n          <div style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:14px;color:var(--text);font-size:0.86rem;\">\n            <div><span class=\"muted\">Agent:</span> <b>${escapeHtml(c.agentName)}</b></div>\n            <div><span class=\"muted\">Lead:</span> <code>${escapeHtml(c.leadPhoneMasked)}</code></div>\n            <div><span class=\"muted\">Status:</span> ${statusBadge(c.status)} (${escapeHtml(c.direction || \"—\")})</div>\n            <div><span class=\"muted\">Talk / Total:</span> ${fmtSeconds(c.answeredSeconds)} / ${fmtSeconds(c.durationSeconds)}</div>\n          </div>\n        `;\n\n        if (aj) {\n          html += `\n            <div style=\"background:var(--surface-2);padding:12px;border-radius:8px;margin-bottom:14px;color:var(--text);\">\n              <div style=\"font-weight:600;margin-bottom:6px;\">AI Summary (${a.provider}/${a.model})</div>\n              <div style=\"font-size:0.88rem;\">${escapeHtml(aj.summary || \"\")}</div>\n              <div style=\"margin-top:10px;display:flex;flex-wrap:wrap;gap:8px;\">\n                <span class=\"badge blue\">Intent: ${escapeHtml(a.intent)}</span>\n                <span class=\"badge amber\">Outcome: ${escapeHtml(a.callOutcome)}</span>\n                <span class=\"badge green\">QA Score: ${a.qualityScore}/100</span>\n                <span class=\"badge gray\">Est. Prob (non-CRM): ${a.conversionProbability}%</span>\n              </div>\n              ${aj.uncertaintyNotes ? `<div style=\"margin-top:8px;font-size:0.8rem;color:#fcd34d;\">Note: ${escapeHtml(aj.uncertaintyNotes)}</div>` : \"\"}\n            </div>\n          `;\n          if (Array.isArray(aj.objections) && aj.objections.length) {\n            html += `<div style=\"margin-bottom:12px;\"><b style=\"color:var(--text);\">Objections</b><ul>${aj.objections\n              .map((o) => `<li><b>${escapeHtml(o.category)}:</b> ${escapeHtml(o.description)} <i>\"${escapeHtml(o.evidence)}\"</i></li>`)\n              .join(\"\")}</ul></div>`;\n          }\n        } else {\n          html += `<div style=\"margin-bottom:14px;\">No AI analysis yet. <button id=\"analyzeNowBtn\" class=\"primary\">Transcribe &amp; Analyze Now</button></div>`;\n        }\n\n        html += `\n          <div style=\"margin-top:12px;\">\n            <button id=\"loadTranscriptBtn\">Load Protected Transcript (Audit Logged)</button>\n            <div id=\"transcriptContainer\" style=\"margin-top:10px;\"></div>\n          </div>\n        `;\n        body.innerHTML = html;\n\n        const analyzeBtn = document.getElementById(\"analyzeNowBtn\");\n        if (analyzeBtn) {\n          analyzeBtn.addEventListener(\"click\", async () => {\n            analyzeBtn.disabled = true;\n            analyzeBtn.textContent = \"Processing...\";\n            try {\n              await apiFetch(`/api/v1/calls/${callId}/analyze`, { method: \"POST\" });\n              await openCallModal(callId);\n              loadDashboard();\n            } catch (e) {\n              analyzeBtn.textContent = `Error: ${e.message}`;\n            }\n          });\n        }\n\n        document.getElementById(\"loadTranscriptBtn\").addEventListener(\"click\", async (ev) => {\n          const btn = ev.target;\n          btn.disabled = true;\n          btn.textContent = \"Loading...\";\n          try {\n            const tr = await apiFetch(`/api/v1/calls/${callId}/transcript`);\n            document.getElementById(\"transcriptContainer\").innerHTML = `\n              <div class=\"muted\" style=\"margin-bottom:4px;\">Language: ${escapeHtml(tr.language || \"unknown\")} · Quality: ${escapeHtml(tr.qualityFlag || \"ok\")}</div>\n              <pre class=\"transcript-box\">${escapeHtml(tr.content || \"(empty)\")}</pre>\n            `;\n            btn.style.display = \"none\";\n          } catch (e) {\n            btn.textContent = `Unavailable: ${e.message}`;\n          }\n        });\n      } catch (err) {\n        body.innerHTML = `<div style=\"color:#fca5a5;\">Failed to load call: ${escapeHtml(err.message)}</div>`;\n      }\n    }\n\n    function escapeHtml(str) {\n      return String(str ?? \"\")\n        .replaceAll(\"&\", \"&amp;\")\n        .replaceAll(\"<\", \"&lt;\")\n        .replaceAll(\">\", \"&gt;\")\n        .replaceAll('\"', \"&quot;\");\n    }\n\n    // KPI Card click-to-filter bindings\n    document.getElementById(\"cardTotal\").addEventListener(\"click\", () => {\n      clearCrossFilter(false);\n      activeCrossFilter.cardId = \"cardTotal\";\n      loadDashboard().then(scrollToExplorer);\n    });\n    document.getElementById(\"cardAnswered\").addEventListener(\"click\", () => {\n      clearCrossFilter(false);\n      document.getElementById(\"statusFilter\").value = \"answered\";\n      activeCrossFilter.cardId = \"cardAnswered\";\n      loadDashboard().then(scrollToExplorer);\n    });\n    document.getElementById(\"cardMissed\").addEventListener(\"click\", () => {\n      clearCrossFilter(false);\n      document.getElementById(\"statusFilter\").value = \"missed\";\n      activeCrossFilter.cardId = \"cardMissed\";\n      loadDashboard().then(scrollToExplorer);\n    });\n    document.getElementById(\"cardFollowups\").addEventListener(\"click\", () => {\n      clearCrossFilter(false);\n      activeCrossFilter.hasFollowup = true;\n      activeCrossFilter.cardId = \"cardFollowups\";\n      loadDashboard().then(scrollToExplorer);\n    });\n    document.getElementById(\"cardCoverage\").addEventListener(\"click\", () => {\n      clearCrossFilter(false);\n      document.getElementById(\"statusFilter\").value = \"answered\";\n      activeCrossFilter.cardId = \"cardCoverage\";\n      loadDashboard().then(scrollToExplorer);\n    });\n\n    // Wire events\n    document.getElementById(\"datePicker\").value = todayIstYmd();\n    document.getElementById(\"refreshBtn\").addEventListener(\"click\", loadDashboard);\n    document.getElementById(\"searchBtn\").addEventListener(\"click\", loadDashboard);\n    document.getElementById(\"departmentFilter\").addEventListener(\"change\", loadDashboard);\n    document.getElementById(\"statusFilter\").addEventListener(\"change\", loadDashboard);\n    document.getElementById(\"closeModalBtn\").addEventListener(\"click\", () => {\n      document.getElementById(\"callModal\").classList.remove(\"open\");\n    });\n    document.getElementById(\"keyBtn\").addEventListener(\"click\", () => {\n      document.getElementById(\"apiKeyInput\").value = getApiKey();\n      showAuthScreen();\n    });\n    document.getElementById(\"saveKeyBtn\").addEventListener(\"click\", async () => {\n      const val = document.getElementById(\"apiKeyInput\").value.trim();\n      localStorage.setItem(STORAGE_KEY, val);\n      setSelectedAccount(\"\");\n      try {\n        await loadAccountsContext();\n        await loadDashboard();\n      } catch (e) {\n        if (e.message !== \"Unauthorized\") setBanner(`Error: ${e.message}`, true);\n      }\n    });\n\n    document.getElementById(\"accountSwitcher\").addEventListener(\"change\", (ev) => {\n      setSelectedAccount(ev.target.value);\n      document.getElementById(\"departmentFilter\").value = \"\";\n      clearCrossFilter(true);\n    });\n\n    // =========================================================================\n    // Admin Multi-Account & Claude API Keys Modal\n    // =========================================================================\n    function showAccountsMsg(text, isError = false) {\n      const el = document.getElementById(\"accountsMsg\");\n      if (!text) {\n        el.style.display = \"none\";\n        return;\n      }\n      el.style.display = \"flex\";\n      el.className = isError ? \"banner error\" : \"banner\";\n      el.textContent = text;\n    }\n\n    function showKeyReveal(keyData, isNew = false) {\n      const box = document.getElementById(\"newKeyReveal\");\n      const mcpUrl = `${window.location.origin}/mcp`;\n      const scopeLabel = keyData.role === \"admin\"\n        ? \"Admin (All Organizations)\"\n        : `Organization: ${keyData.accountSlug || keyData.tenantId}`;\n      const title = isNew\n        ? `New Claude API Key Created (${escapeHtml(scopeLabel)})`\n        : `Claude API Key — ${escapeHtml(keyData.name || \"Key\")} (${escapeHtml(scopeLabel)})`;\n      box.style.display = \"block\";\n      box.innerHTML = `\n        <div style=\"display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px;\">\n          <b style=\"color:#86efac;\">${title}</b>\n          <div style=\"display:flex;gap:6px;\">\n            <button id=\"copyNewKeyBtn\" class=\"sm primary\">Copy Key</button>\n            <button id=\"hideKeyRevealBtn\" class=\"sm\">Hide</button>\n          </div>\n        </div>\n        <div style=\"margin-bottom:8px;\"><code>${escapeHtml(keyData.apiKey)}</code></div>\n        <div class=\"muted\" style=\"font-size:0.78rem;\">\n          <b>Claude Custom Connector:</b> URL <code>${escapeHtml(mcpUrl)}</code> · Auth: <b>No sign-in</b> · Header: <code>x-api-key</code> = key above · Transport: <b>Streamable HTTP</b>\n        </div>\n      `;\n      document.getElementById(\"copyNewKeyBtn\")?.addEventListener(\"click\", async (ev) => {\n        try {\n          await navigator.clipboard.writeText(keyData.apiKey);\n          ev.target.textContent = \"Copied!\";\n        } catch {\n          ev.target.textContent = \"Copy manually\";\n        }\n      });\n      document.getElementById(\"hideKeyRevealBtn\")?.addEventListener(\"click\", () => {\n        box.style.display = \"none\";\n      });\n    }\n\n    async function revealKeyById(keyId, btn) {\n      if (btn) btn.disabled = true;\n      try {\n        const revealed = await apiFetch(`/api/v1/api-keys/${encodeURIComponent(keyId)}/reveal`, {\n          skipAccountHeader: true,\n        });\n        showKeyReveal(revealed, false);\n        showAccountsMsg(\"\");\n      } catch (e) {\n        showAccountsMsg(e.message, true);\n      } finally {\n        if (btn) btn.disabled = false;\n      }\n    }\n\n    async function refreshAccountsModal() {\n      document.getElementById(\"mcpUrlDisplay\").textContent = `${window.location.origin}/mcp`;\n      const [accRes, keysRes] = await Promise.all([\n        apiFetch(\"/api/v1/accounts\", { skipAccountHeader: true }),\n        apiFetch(\"/api/v1/api-keys\", { skipAccountHeader: true }),\n      ]);\n      const accounts = accRes.accounts || [];\n      const keys = keysRes.keys || [];\n      const accountNameById = Object.fromEntries(accounts.map((a) => [a.id, a.slug || a.name]));\n      const activeKeyByTenantId = {};\n      for (const k of keys) {\n        if (k.active && k.role === \"tenant\" && k.tenantId && !activeKeyByTenantId[k.tenantId]) {\n          activeKeyByTenantId[k.tenantId] = k;\n        }\n      }\n\n      document.getElementById(\"orgsCountLabel\").textContent = `${accounts.length} organization${accounts.length === 1 ? \"\" : \"s\"}`;\n      document.getElementById(\"orgsTableBody\").innerHTML = accounts.length\n        ? accounts\n            .map((a) => {\n              const slug = a.slug || a.id;\n              const existingKey = activeKeyByTenantId[a.id];\n              const keyBtnHtml = existingKey\n                ? `<button class=\"sm primary\" data-show-key=\"${escapeHtml(existingKey.id)}\">Show Claude Key</button>`\n                : `<button class=\"sm primary\" data-gen-key=\"${escapeHtml(slug)}\" data-org-name=\"${escapeHtml(a.name)}\">Generate Claude Key</button>`;\n              return `\n                <tr>\n                  <td><b>${escapeHtml(a.name)}</b></td>\n                  <td><code>${escapeHtml(slug)}</code></td>\n                  <td>${a.hasSmartfloCredentials ? `<span class=\"badge green\">Configured</span>` : `<span class=\"badge amber\">Missing</span>`}</td>\n                  <td>${a.active ? `<span class=\"badge green\">Active</span>` : `<span class=\"badge gray\">Inactive</span>`}</td>\n                  <td style=\"display:flex;gap:6px;flex-wrap:wrap;\">\n                    <button class=\"sm\" data-switch-org=\"${escapeHtml(slug)}\">Switch</button>\n                    <button class=\"sm\" data-edit-org=\"${escapeHtml(a.id)}\">Edit</button>\n                    ${keyBtnHtml}\n                  </td>\n                </tr>`;\n            })\n            .join(\"\")\n        : `<tr><td colspan=\"5\" class=\"muted\">No organizations found.</td></tr>`;\n\n      document.querySelectorAll(\"button[data-switch-org]\").forEach((btn) => {\n        btn.addEventListener(\"click\", () => {\n          setSelectedAccount(btn.dataset.switchOrg);\n          document.getElementById(\"accountSwitcher\").value = btn.dataset.switchOrg;\n          document.getElementById(\"accountsModal\").classList.remove(\"open\");\n          document.getElementById(\"departmentFilter\").value = \"\";\n          clearCrossFilter(true);\n        });\n      });\n\n      document.querySelectorAll(\"button[data-edit-org]\").forEach((btn) => {\n        btn.addEventListener(\"click\", async () => {\n          const targetId = btn.dataset.editOrg;\n          btn.disabled = true;\n          try {\n            const creds = await apiFetch(`/api/v1/accounts/${encodeURIComponent(targetId)}/credentials`, {\n              skipAccountHeader: true,\n            });\n            document.getElementById(\"editOrgId\").value = creds.id;\n            document.getElementById(\"editOrgOldSlug\").value = creds.slug || creds.id;\n            document.getElementById(\"editOrgName\").value = creds.name || \"\";\n            document.getElementById(\"editOrgSlug\").value = creds.slug || \"\";\n            document.getElementById(\"editOrgTz\").value = creds.timezone || \"Asia/Kolkata\";\n            const apiKeyInput = document.getElementById(\"editOrgApiKey\");\n            apiKeyInput.type = \"password\";\n            apiKeyInput.value = creds.smartfloApiKey || \"\";\n            document.getElementById(\"toggleEditApiKeyBtn\").textContent = \"Show\";\n            document.getElementById(\"editOrgEmail\").value = creds.smartfloEmail || \"\";\n            document.getElementById(\"editOrgActive\").value = creds.active ? \"true\" : \"false\";\n            document.getElementById(\"editOrgCard\").style.display = \"block\";\n            document.getElementById(\"editOrgName\").focus();\n          } catch (e) {\n            showAccountsMsg(`Failed to load organization details: ${e.message}`, true);\n          } finally {\n            btn.disabled = false;\n          }\n        });\n      });\n\n      document.querySelectorAll(\"button[data-gen-key]\").forEach((btn) => {\n        btn.addEventListener(\"click\", async () => {\n          const slug = btn.dataset.genKey;\n          const orgName = btn.dataset.orgName;\n          const label = window.prompt(`Label for ${orgName}'s Claude API key:`, `${orgName} Claude Key`);\n          if (!label || !label.trim()) return;\n          btn.disabled = true;\n          try {\n            const created = await apiFetch(`/api/v1/accounts/${encodeURIComponent(slug)}/api-keys`, {\n              method: \"POST\",\n              skipAccountHeader: true,\n              body: JSON.stringify({ name: label.trim() }),\n            });\n            showKeyReveal(created, true);\n            showAccountsMsg(`Issued dedicated Claude key for ${orgName}.`);\n            await refreshAccountsModal();\n          } catch (e) {\n            showAccountsMsg(`Failed to issue key: ${e.message}`, true);\n          } finally {\n            btn.disabled = false;\n          }\n        });\n      });\n\n      document.getElementById(\"apiKeysTableBody\").innerHTML = keys.length\n        ? keys\n            .map((k) => {\n              const scope = k.role === \"admin\" ? \"All Orgs\" : (accountNameById[k.tenantId] || k.tenantId || \"—\");\n              const lastUsed = k.lastUsedAt\n                ? new Date(k.lastUsedAt).toLocaleString(\"en-IN\", { timeZone: \"Asia/Kolkata\" })\n                : \"Never\";\n              return `\n                <tr>\n                  <td><b>${escapeHtml(k.name)}</b> <span class=\"muted\">(${escapeHtml(scope)})</span></td>\n                  <td><span class=\"badge ${k.role === \"admin\" ? \"blue\" : \"amber\"}\">${escapeHtml(k.role)}</span></td>\n                  <td><code>${escapeHtml(k.keyPrefix)}…</code></td>\n                  <td class=\"muted\">${escapeHtml(lastUsed)}</td>\n                  <td>${k.active ? `<span class=\"badge green\">Active</span>` : `<span class=\"badge red\">Revoked</span>`}</td>\n                  <td style=\"display:flex;gap:6px;flex-wrap:wrap;\">\n                    ${k.active && k.canReveal ? `<button class=\"sm\" data-show-key=\"${escapeHtml(k.id)}\">Show</button>` : \"\"}\n                    <button class=\"sm danger\" data-revoke-key=\"${escapeHtml(k.id)}\">Delete</button>\n                  </td>\n                </tr>`;\n            })\n            .join(\"\")\n        : `<tr><td colspan=\"6\" class=\"muted\">No issued API keys yet (using bootstrap MCP_API_KEY).</td></tr>`;\n\n      document.querySelectorAll(\"button[data-show-key]\").forEach((btn) => {\n        btn.addEventListener(\"click\", () => revealKeyById(btn.dataset.showKey, btn));\n      });\n\n      document.querySelectorAll(\"button[data-revoke-key]\").forEach((btn) => {\n        btn.addEventListener(\"click\", async () => {\n          if (!window.confirm(\"Delete this Claude API key? Any Claude connector using it will stop working, and you can generate a new one.\")) return;\n          btn.disabled = true;\n          try {\n            await apiFetch(`/api/v1/api-keys/${encodeURIComponent(btn.dataset.revokeKey)}`, {\n              method: \"DELETE\",\n              skipAccountHeader: true,\n            });\n            document.getElementById(\"newKeyReveal\").style.display = \"none\";\n            showAccountsMsg(\"API key deleted. You can generate a new key anytime.\");\n            await refreshAccountsModal();\n          } catch (e) {\n            showAccountsMsg(`Failed to delete key: ${e.message}`, true);\n          }\n        });\n      });\n    }\n\n    document.getElementById(\"accountsBtn\").addEventListener(\"click\", async () => {\n      document.getElementById(\"accountsModal\").classList.add(\"open\");\n      document.getElementById(\"newKeyReveal\").style.display = \"none\";\n      document.getElementById(\"editOrgCard\").style.display = \"none\";\n      showAccountsMsg(\"\");\n      try {\n        await refreshAccountsModal();\n      } catch (e) {\n        showAccountsMsg(`Failed to load accounts: ${e.message}`, true);\n      }\n    });\n\n    document.getElementById(\"cancelEditOrgBtn\").addEventListener(\"click\", () => {\n      document.getElementById(\"editOrgCard\").style.display = \"none\";\n    });\n\n    document.getElementById(\"toggleEditApiKeyBtn\").addEventListener(\"click\", (ev) => {\n      const input = document.getElementById(\"editOrgApiKey\");\n      const showing = input.type === \"text\";\n      input.type = showing ? \"password\" : \"text\";\n      ev.target.textContent = showing ? \"Show\" : \"Hide\";\n    });\n\n    document.getElementById(\"saveEditOrgBtn\").addEventListener(\"click\", async (ev) => {\n      const btn = ev.target;\n      const id = document.getElementById(\"editOrgId\").value;\n      const oldSlug = document.getElementById(\"editOrgOldSlug\").value;\n      const name = document.getElementById(\"editOrgName\").value.trim();\n      const slug = document.getElementById(\"editOrgSlug\").value.trim();\n      const timezone = document.getElementById(\"editOrgTz\").value.trim() || \"Asia/Kolkata\";\n      const smartfloApiKey = document.getElementById(\"editOrgApiKey\").value.trim();\n      const smartfloEmail = document.getElementById(\"editOrgEmail\").value.trim();\n      const active = document.getElementById(\"editOrgActive\").value === \"true\";\n\n      if (!name) {\n        showAccountsMsg(\"Organization Name is required.\", true);\n        return;\n      }\n\n      btn.disabled = true;\n      btn.textContent = \"Saving...\";\n      try {\n        const payload = { name, timezone, active };\n        if (slug) payload.slug = slug;\n        if (smartfloApiKey) payload.smartfloApiKey = smartfloApiKey;\n        if (smartfloEmail) payload.smartfloEmail = smartfloEmail;\n\n        const updated = await apiFetch(`/api/v1/accounts/${encodeURIComponent(id)}`, {\n          method: \"PATCH\",\n          skipAccountHeader: true,\n          body: JSON.stringify(payload),\n        });\n\n        if (getSelectedAccount() === oldSlug || getSelectedAccount() === id) {\n          setSelectedAccount(updated.slug || updated.id);\n        }\n        document.getElementById(\"editOrgCard\").style.display = \"none\";\n        showAccountsMsg(`Updated organization \"${updated.name}\" (${updated.slug}).`);\n        await loadAccountsContext();\n        await refreshAccountsModal();\n      } catch (e) {\n        showAccountsMsg(`Failed to update organization: ${e.message}`, true);\n      } finally {\n        btn.disabled = false;\n        btn.textContent = \"Save Changes\";\n      }\n    });\n\n    document.getElementById(\"closeAccountsModalBtn\").addEventListener(\"click\", () => {\n      document.getElementById(\"accountsModal\").classList.remove(\"open\");\n    });\n\n    document.getElementById(\"newOrgName\").addEventListener(\"input\", (ev) => {\n      const slugInput = document.getElementById(\"newOrgSlug\");\n      if (!slugInput.dataset.touched) {\n        slugInput.value = ev.target.value\n          .toLowerCase()\n          .replace(/[^a-z0-9]+/g, \"-\")\n          .replace(/^-+|-+$/g, \"\");\n      }\n    });\n    document.getElementById(\"newOrgSlug\").addEventListener(\"input\", (ev) => {\n      ev.target.dataset.touched = ev.target.value ? \"1\" : \"\";\n    });\n\n    document.getElementById(\"createOrgBtn\").addEventListener(\"click\", async (ev) => {\n      const btn = ev.target;\n      const name = document.getElementById(\"newOrgName\").value.trim();\n      const slug = document.getElementById(\"newOrgSlug\").value.trim();\n      const timezone = document.getElementById(\"newOrgTz\").value.trim() || \"Asia/Kolkata\";\n      const smartfloApiKey = document.getElementById(\"newOrgApiKey\").value.trim();\n      const smartfloEmail = document.getElementById(\"newOrgEmail\").value.trim();\n      const smartfloPassword = document.getElementById(\"newOrgPassword\").value;\n\n      if (!name) {\n        showAccountsMsg(\"Organization Name is required.\", true);\n        return;\n      }\n      if (!smartfloApiKey && !(smartfloEmail && smartfloPassword)) {\n        showAccountsMsg(\"Provide either a Smartflo Portal API Token or Smartflo Email + Password.\", true);\n        return;\n      }\n\n      btn.disabled = true;\n      btn.textContent = \"Adding...\";\n      try {\n        const payload = { name, timezone };\n        if (slug) payload.slug = slug;\n        if (smartfloApiKey) payload.smartfloApiKey = smartfloApiKey;\n        if (smartfloEmail) payload.smartfloEmail = smartfloEmail;\n        if (smartfloPassword) payload.smartfloPassword = smartfloPassword;\n\n        const created = await apiFetch(\"/api/v1/accounts\", {\n          method: \"POST\",\n          skipAccountHeader: true,\n          body: JSON.stringify(payload),\n        });\n        document.getElementById(\"newOrgName\").value = \"\";\n        document.getElementById(\"newOrgSlug\").value = \"\";\n        document.getElementById(\"newOrgSlug\").dataset.touched = \"\";\n        document.getElementById(\"newOrgApiKey\").value = \"\";\n        document.getElementById(\"newOrgEmail\").value = \"\";\n        document.getElementById(\"newOrgPassword\").value = \"\";\n        showAccountsMsg(`Added organization \"${created.name}\" (${created.slug}). You can now switch to it or generate its Claude API key.`);\n        await loadAccountsContext();\n        await refreshAccountsModal();\n      } catch (e) {\n        showAccountsMsg(`Failed to add organization: ${e.message}`, true);\n      } finally {\n        btn.disabled = false;\n        btn.textContent = \"Add Organization\";\n      }\n    });\n\n    document.getElementById(\"issueAdminKeyBtn\").addEventListener(\"click\", async (ev) => {\n      const label = window.prompt(\"Label for the Admin Claude API key (accesses all orgs):\", \"Admin Claude Key\");\n      if (!label || !label.trim()) return;\n      const btn = ev.target;\n      btn.disabled = true;\n      try {\n        const created = await apiFetch(\"/api/v1/admin/api-keys\", {\n          method: \"POST\",\n          skipAccountHeader: true,\n          body: JSON.stringify({ name: label.trim() }),\n        });\n        showKeyReveal(created, true);\n        showAccountsMsg(\"Issued new Admin API key (all organizations).\");\n        await refreshAccountsModal();\n      } catch (e) {\n        showAccountsMsg(`Failed to issue admin key: ${e.message}`, true);\n      } finally {\n        btn.disabled = false;\n      }\n    });\n\n    function renderOutcomeChart(rows) {\n      const box = document.getElementById(\"outcomeChartBox\");\n      const meta = document.getElementById(\"outcomeMeta\");\n      const total = rows.reduce((sum, r) => sum + (r.count || 0), 0);\n      meta.textContent = `${total} analyzed`;\n      if (!total) {\n        box.innerHTML = `<div class=\"muted\">No analyzed calls yet for this date. Click \"Process Pending (All)\" to generate outcome insights.</div>`;\n        return;\n      }\n\n      const palette = {\n        interested: \"#22c55e\",\n        verbal_commitment: \"#10b981\",\n        callback_requested: \"#f59e0b\",\n        information_requested: \"#4f8cff\",\n        not_interested: \"#ef4444\",\n        not_connected: \"#a855f7\",\n        unknown: \"#64748b\",\n      };\n\n      const radius = 56;\n      const circumference = 2 * Math.PI * radius;\n      let offset = 0;\n      const circles = rows\n        .map((r) => {\n          const pct = r.count / total;\n          const len = pct * circumference;\n          const color = palette[r.outcome] || \"#94a3b8\";\n          const seg = `<circle cx=\"74\" cy=\"74\" r=\"${radius}\" fill=\"transparent\" stroke=\"${color}\" stroke-width=\"18\" stroke-dasharray=\"${len} ${circumference - len}\" stroke-dashoffset=\"${-offset}\" transform=\"rotate(-90 74 74)\" />`;\n          offset += len;\n          return seg;\n        })\n        .join(\"\");\n\n      const legend = rows\n        .map((r) => {\n          const pct = Math.round((r.count / total) * 100);\n          const color = palette[r.outcome] || \"#94a3b8\";\n          const label = String(r.outcome || \"unknown\").replaceAll(\"_\", \" \");\n          const isSelected = activeCrossFilter.outcome === r.outcome;\n          return `\n            <div class=\"outcome-row ${isSelected ? \"active-filter\" : \"\"}\" data-outcome=\"${escapeHtml(r.outcome)}\" title=\"Click to filter calls with outcome: ${escapeHtml(label)}\">\n              <div class=\"outcome-row-top\">\n                <span style=\"text-transform:capitalize;\"><span class=\"outcome-dot\" style=\"background:${color};\"></span>${escapeHtml(label)}</span>\n                <span><b>${r.count}</b> <span class=\"muted\">(${pct}%)</span></span>\n              </div>\n              <div class=\"mini-bar\"><div style=\"width:${pct}%;background:${color};\"></div></div>\n            </div>`;\n        })\n        .join(\"\");\n\n      box.innerHTML = `\n        <div class=\"donut-box\">\n          <svg width=\"148\" height=\"148\" viewBox=\"0 0 148 148\">\n            <circle cx=\"74\" cy=\"74\" r=\"${radius}\" fill=\"transparent\" stroke=\"rgba(148,163,184,0.12)\" stroke-width=\"18\" />\n            ${circles}\n          </svg>\n          <div class=\"donut-center\">\n            <div class=\"donut-total\">${total}</div>\n            <div class=\"donut-sub\">Analyzed</div>\n          </div>\n        </div>\n        <div class=\"outcome-legend\">${legend}</div>\n      `;\n\n      box.querySelectorAll(\".outcome-row[data-outcome]\").forEach((row) => {\n        row.addEventListener(\"click\", () => {\n          const val = row.dataset.outcome;\n          activeCrossFilter.outcome = activeCrossFilter.outcome === val ? \"\" : val;\n          loadDashboard().then(scrollToExplorer);\n        });\n      });\n    }\n\n    let autoProcessing = false;\n\n    async function runAutoProcessLoop(btn) {\n      if (autoProcessing) {\n        autoProcessing = false;\n        btn.textContent = \"Stopping...\";\n        return;\n      }\n      autoProcessing = true;\n      btn.textContent = \"Stop Auto-Process\";\n      let totalDone = 0;\n\n      try {\n        while (autoProcessing) {\n          setBanner(`Auto-transcribing & analyzing pending calls... (${totalDone} completed this run)`);\n          const res = await apiFetch(\"/api/v1/queues/enqueue-pending\", {\n            method: \"POST\",\n            body: JSON.stringify({ limit: 50 }),\n          });\n\n          if (res.mode === \"queue\") {\n            setBanner(`Enqueued ${res.enqueued} calls into BullMQ worker.`);\n            await loadDashboard();\n            break;\n          }\n\n          totalDone += res.processed || 0;\n          await loadDashboard();\n\n          if (!res.remaining || (res.processed === 0 && res.failed === 0)) {\n            setBanner(`Auto-processing complete! Processed ${totalDone} calls.`);\n            break;\n          }\n          // Brief pause between serverless batches\n          await new Promise((r) => setTimeout(r, 400));\n        }\n      } catch (e) {\n        setBanner(`Auto-process paused: ${e.message}`, true);\n      } finally {\n        autoProcessing = false;\n        btn.disabled = false;\n        btn.textContent = \"Process Pending (All)\";\n      }\n    }\n\n    document.getElementById(\"syncBtn\").addEventListener(\"click\", async (ev) => {\n      const btn = ev.target;\n      const dateYmd = document.getElementById(\"datePicker\").value || todayIstYmd();\n      const { from, to } = getSelectedDayRange(dateYmd);\n      btn.disabled = true;\n      btn.textContent = \"Syncing...\";\n      try {\n        const res = await apiFetch(\"/api/v1/sync/calls\", {\n          method: \"POST\",\n          body: JSON.stringify({ from, to }),\n        });\n        setBanner(`Synced ${res.callsFetched} calls (${res.newCalls} new, ${res.updatedCalls} updated). Starting auto-analysis...`);\n        await loadDashboard();\n        // Automatically transcribe & analyze any newly synced pending calls\n        runAutoProcessLoop(document.getElementById(\"enqueueBtn\"));\n      } catch (e) {\n        setBanner(`Sync failed: ${e.message}`, true);\n      } finally {\n        btn.disabled = false;\n        btn.textContent = \"Sync Day\";\n      }\n    });\n\n    document.getElementById(\"enqueueBtn\").addEventListener(\"click\", (ev) => {\n      runAutoProcessLoop(ev.target);\n    });\n\n    // Floating Bot open / close / auto-expand + Frequent Question Badges\n    const FAQ_STORAGE_KEY = \"smartflow_faq_counts\";\n    const botFab = document.getElementById(\"botFab\");\n    const botPanel = document.getElementById(\"botPanel\");\n    const botExpandBtn = document.getElementById(\"botExpandBtn\");\n\n    function setBotExpanded(expanded) {\n      botPanel.classList.toggle(\"expanded\", expanded);\n      botExpandBtn.textContent = expanded ? \"Compact\" : \"Expand\";\n    }\n\n    botFab.addEventListener(\"click\", () => {\n      botPanel.classList.add(\"open\");\n      botFab.style.display = \"none\";\n      document.getElementById(\"botInput\").focus();\n    });\n    document.getElementById(\"botCloseBtn\").addEventListener(\"click\", () => {\n      botPanel.classList.remove(\"open\");\n      botFab.style.display = \"flex\";\n    });\n    botExpandBtn.addEventListener(\"click\", () => {\n      setBotExpanded(!botPanel.classList.contains(\"expanded\"));\n    });\n\n    function loadFaqMap() {\n      try {\n        return JSON.parse(localStorage.getItem(FAQ_STORAGE_KEY) || \"{}\");\n      } catch {\n        return {};\n      }\n    }\n\n    function recordFrequentQuestion(q) {\n      const normalized = q.trim();\n      if (!normalized) return;\n      const map = loadFaqMap();\n      map[normalized] = (map[normalized] || 0) + 1;\n      localStorage.setItem(FAQ_STORAGE_KEY, JSON.stringify(map));\n      renderFrequentBadges();\n    }\n\n    function renderFrequentBadges() {\n      const map = loadFaqMap();\n      const frequent = Object.entries(map)\n        .filter(([, count]) => count >= 2)\n        .sort((a, b) => b[1] - a[1])\n        .slice(0, 6);\n\n      const wrap = document.getElementById(\"frequentWrap\");\n      const container = document.getElementById(\"frequentChips\");\n      if (!frequent.length) {\n        wrap.style.display = \"none\";\n        return;\n      }\n      wrap.style.display = \"block\";\n      container.innerHTML = frequent\n        .map(([text, count]) => {\n          const shortLabel = text.length > 36 ? text.slice(0, 35) + \"…\" : text;\n          return `<button class=\"chip frequent\" data-q=\"${escapeHtml(text)}\" title=\"${escapeHtml(text)}\">★ ${escapeHtml(shortLabel)} (${count}×)</button>`;\n        })\n        .join(\"\");\n\n      container.querySelectorAll(\".chip[data-q]\").forEach((chip) => {\n        chip.addEventListener(\"click\", () => askBot(chip.dataset.q));\n      });\n    }\n\n    async function askBot(questionText) {\n      const input = document.getElementById(\"botInput\");\n      const btn = document.getElementById(\"botAskBtn\");\n      const box = document.getElementById(\"botMessages\");\n      const q = (questionText ?? input.value).trim();\n      if (!q) return;\n\n      // Auto-expand chat panel when user chats\n      botPanel.classList.add(\"open\");\n      botFab.style.display = \"none\";\n      setBotExpanded(true);\n      recordFrequentQuestion(q);\n\n      input.value = \"\";\n      btn.disabled = true;\n      btn.textContent = \"Thinking...\";\n\n      const userDiv = document.createElement(\"div\");\n      userDiv.className = \"bot-msg user\";\n      userDiv.textContent = q;\n      box.appendChild(userDiv);\n\n      const loadingDiv = document.createElement(\"div\");\n      loadingDiv.className = \"bot-msg muted\";\n      loadingDiv.textContent = \"Running approved SQL analytics tools & synthesizing answer...\";\n      box.appendChild(loadingDiv);\n      box.scrollTop = box.scrollHeight;\n\n      try {\n        const dateYmd = document.getElementById(\"datePicker\").value || todayIstYmd();\n        const res = await apiFetch(\"/api/v1/ask\", {\n          method: \"POST\",\n          body: JSON.stringify({ question: q, date: dateYmd, timezone: \"Asia/Kolkata\" }),\n        });\n\n        const pointsHtml = (res.keyPoints || [])\n          .map((p) => `<li>${escapeHtml(p)}</li>`)\n          .join(\"\");\n        const caveatsHtml = (res.caveats || []).length\n          ? `<div style=\"margin-top:8px;font-size:0.78rem;color:#fcd34d;\">Caveat: ${res.caveats.map(escapeHtml).join(\" · \")}</div>`\n          : \"\";\n        const toolsHtml = (res.toolsUsed || [])\n          .map((t) => `<span class=\"badge blue\">${escapeHtml(t)}</span>`)\n          .join(\"\");\n\n        loadingDiv.className = \"bot-msg\";\n        loadingDiv.innerHTML = `\n          <div class=\"bot-headline\">${escapeHtml(res.headline)}</div>\n          <div>${escapeHtml(res.answer)}</div>\n          ${pointsHtml ? `<ul class=\"bot-points\">${pointsHtml}</ul>` : \"\"}\n          ${caveatsHtml}\n          <div class=\"bot-meta\"><span>Tools used:</span> ${toolsHtml}</div>\n        `;\n      } catch (e) {\n        loadingDiv.className = \"bot-msg\";\n        loadingDiv.innerHTML = `<span style=\"color:#fca5a5;\">Failed to answer: ${escapeHtml(e.message)}</span>`;\n      } finally {\n        btn.disabled = false;\n        btn.textContent = \"Ask\";\n        box.scrollTop = box.scrollHeight;\n      }\n    }\n\n    document.getElementById(\"botAskBtn\").addEventListener(\"click\", () => askBot());\n    document.getElementById(\"botInput\").addEventListener(\"keydown\", (e) => {\n      if (e.key === \"Enter\") askBot();\n    });\n    document.querySelectorAll(\"#starterChips .chip[data-q]\").forEach((chip) => {\n      chip.addEventListener(\"click\", () => askBot(chip.dataset.q));\n    });\n    renderFrequentBadges();\n\n    // Boot\n    if (!getApiKey()) {\n      showAuthScreen();\n    } else {\n      loadAccountsContext()\n        .then(() => loadDashboard())\n        .catch((e) => {\n          if (e.message !== \"Unauthorized\") setBanner(`Error: ${e.message}`, true);\n        });\n    }\n  </script>\n</body>\n</html>\n\n";
